window.SEARCH=[{"t": "Our rooms", "u": "/straand-preview/en/stay/", "x": "From historic log-walled rooms to demi-suites with a balcony. All 125 rooms have TV and wifi.", "k": "Stay"}, {"t": "Eat & drink", "u": "/straand-preview/en/eat-and-drink/", "x": "From breakfast to dinner overlooking Lake Nisser. We call it \"the taste of Telemark\".", "k": "Eat & drink"}, {"t": "Experiences in Vrådal", "u": "/straand-preview/en/experiences/", "x": "Winter, spring, summer and autumn: everything starts at the hotel, in Norway in miniature.", "k": "Experiences"}, {"t": "The vintage boat MS Fram", "u": "/straand-preview/en/experiences/ms-fram/", "x": "The hotel's 1909 boat, from the Straand jetty through the locks on Lake Nisser and Vråvatn.", "k": "MS Fram"}, {"t": "Meetings and conferences in Telemark – for up to 600 people", "u": "/straand-preview/en/meetings-and-conferences/", "x": "The 660 m² Vrådal Hall seats 400 classroom-style and 600 theatre-style, with its own breakout rooms. Rooms, food and activities by Lake Nisser in Vrådal.", "k": "Meetings & conferences"}, {"t": "Celebrations at Straand Hotel", "u": "/straand-preview/en/celebrations/", "x": "Weddings, confirmations, anniversaries and memorials in historic surroundings by Lake Nisser.", "k": "Celebrations & weddings"}, {"t": "The story of Straand", "u": "/straand-preview/en/about/history/", "x": "From coaching inn in 1864 to the fifth generation today.", "k": "History"}, {"t": "Contact us", "u": "/straand-preview/en/about/contact/", "x": "Reception is open 24 hours. Call, write or drop by.", "k": "Contact"}, {"t": "Privacy policy", "u": "/straand-preview/en/privacy/", "x": "How STRAAND HOTEL AS processes personal data.", "k": "Privacy"}, {"t": "Cookies", "u": "/straand-preview/en/cookies/", "x": "Which cookies straand.no uses, and how to change your consent.", "k": "Cookies"}, {"t": "Legal information", "u": "/straand-preview/en/legal/", "x": "Who runs this website, with contact details and company number.", "k": "Legal information"}, {"t": "Practical information", "u": "/straand-preview/en/stay/practical-information/", "x": "Check-in and check-out, meals, pool, payment and everything to know before your stay.", "k": "Practical information"}, {"t": "Events at Straand", "u": "/straand-preview/en/experiences/events/", "x": "Festival, meets, Christmas parties and concerts through the year.", "k": "Events"}, {"t": "About Straand Hotel", "u": "/straand-preview/en/about/", "x": "A family-run hotel in Vrådal since 1864, today hosted by the fifth generation.", "k": "About Straand"}, {"t": "Things to see and do near Straand", "u": "/straand-preview/en/experiences/things-to-do/", "x": "The best things to see and do while you stay with us: at the hotel, in Vrådal and on day trips around Telemark.", "k": "Explore Vrådal"}, {"t": "Getting here and parking", "u": "/straand-preview/en/about/getting-here/", "x": "Free parking next to the hotel, EV charging and a bus stop at the door. 2–3 hours from Kristiansand and Larvik.", "k": "Getting here & parking"}, {"t": "Motorcycling and HUBRiding", "u": "/straand-preview/en/experiences/motorcycling/", "x": "Norway's first Bikers Welcome hotel. Stay at Straand, unpack once and ride a new route every day.", "k": "Motorcycling"}, {"t": "Questions & answers", "u": "/straand-preview/en/about/faq/", "x": "", "k": "Questions & answers"}, {"t": "Blog & news", "u": "/straand-preview/en/blog/", "x": "Tips and stories from Vrådal, written by the hosts.", "k": "Blog"}, {"t": "Historic rooms", "u": "/straand-preview/en/stay/historic-rooms/", "x": "Single and double rooms in the old wing, with log walls and traditional furniture. TV, desk and shower room.", "k": "Stay"}, {"t": "Standard double", "u": "/straand-preview/en/stay/standard-double/", "x": "Two singles or a double bed, desk, armchair or sofa and TV. Bathroom with shower or bath.", "k": "Stay"}, {"t": "Family room", "u": "/straand-preview/en/stay/family-room/", "x": "Double bed and a double sofa bed, desk and TV. Shower room.", "k": "Stay"}, {"t": "Demi-suite", "u": "/straand-preview/en/stay/demi-suite/", "x": "Bedroom on the first floor, living room with sofa bed and balcony on the second. Coffee machine and phone.", "k": "Stay"}, {"t": "Accessible room", "u": "/straand-preview/en/stay/accessible-room/", "x": "Wide doors, a large bathroom and room for a wheelchair. Sofa bed for a companion. We have two.", "k": "Stay"}, {"t": "Single room", "u": "/straand-preview/en/stay/single-room/", "x": "Bed, desk and TV. Shower room. Travelling alone suits Straand too.", "k": "Stay"}, {"t": "The restaurant", "u": "/straand-preview/en/eat-and-drink/restaurant/", "x": "Breakfast and dinner overlooking Lake Nisser. Evening buffet in summer, otherwise adapted to the number of guests.", "k": "Eat & drink"}, {"t": "The terrace", "u": "/straand-preview/en/eat-and-drink/terrace/", "x": "Lunch, coffee and ice cream in the sun. One of the hotel's favourite spots on a fine day.", "k": "Eat & drink"}, {"t": "Fram Bar", "u": "/straand-preview/en/eat-and-drink/fram-bar/", "x": "Coffee, cocktails and light dishes. The meeting place before and after the day's adventures.", "k": "Eat & drink"}, {"t": "The beach bar", "u": "/straand-preview/en/eat-and-drink/beach-bar/", "x": "Our own beach club on Lake Nisser, with swimming, SUP, kayaks and simple summer food.", "k": "Eat & drink"}, {"t": "The wine cellar", "u": "/straand-preview/en/eat-and-drink/wine-cellar/", "x": "A historic cellar for private dinners, wine tastings and small parties.", "k": "Eat & drink"}, {"t": "MS Fram", "u": "/straand-preview/en/experiences/ms-fram/", "x": "The 1909 vintage boat sails through the Småstraum and Storstraum locks, with refreshments on board.", "k": "Eat & drink"}, {"t": "Winter", "u": "/straand-preview/en/experiences/winter/", "x": "Ski slopes, forest trails, fireside evenings, the pool and sauna, and play for the children.", "k": "Experiences"}, {"t": "Spring", "u": "/straand-preview/en/experiences/spring/", "x": "The golf course on Fossøy opens, the bikes come out and the first motorcycles find their way to Vrådal.", "k": "Experiences"}, {"t": "Summer", "u": "/straand-preview/en/experiences/summer/", "x": "The jetty, the beach club, MS Fram and long evenings on the terrace. Straand is made for families.", "k": "Experiences"}, {"t": "Autumn", "u": "/straand-preview/en/experiences/autumn/", "x": "Venelifjellet in autumn colours, berries and mushrooms in the forest, game on the menu and the fire lit at night.", "k": "Experiences"}, {"t": "The Straand Festival", "u": "/straand-preview/en/experiences/events/straand-festival/", "x": "30 Oct – 1 Nov: The annual music and dance festival, with Norwegian dance music on several stages all weekend.", "k": "What's on at Straand"}, {"t": "Christmas parties", "u": "/straand-preview/en/christmas-parties/", "x": "Six weekends before Christmas: Home-made Christmas food in the historic lounges, with a show and entertainment. Rooms are booked separately.", "k": "What's on at Straand"}, {"t": "Hotel car park", "u": "/straand-preview/en/about/getting-here/#parkering", "x": "Free outdoor parking for cars and motorcycles, approx. 100 spaces, in view of the hotel.", "k": "Getting here & parking"}, {"t": "EV charging for guests", "u": "/straand-preview/en/about/getting-here/#lading-tesla", "x": "3 chargers (Type 2, 7.4 kW) for hotel guests, open 24 hours.", "k": "Getting here & parking"}, {"t": "EV charging Charge365", "u": "/straand-preview/en/about/getting-here/#lading-charge365", "x": "6 chargers, paid in the app.", "k": "Getting here & parking"}, {"t": "Bus stop \"Straand\"", "u": "/straand-preview/en/about/getting-here/#buss", "x": "The stop is right next to the hotel.", "k": "Getting here & parking"}, {"t": "Lock cruise on the veteran boat MS Fram", "u": "/straand-preview/en/experiences/things-to-do/#ms-fram", "x": "The hotel's own 1909 veteran boat leaves the Straand jetty for lakes Nisser and Vråvatn, passing through the Småstraum lock. Sails May to October.", "k": "Explore Vrådal"}, {"t": "Straand Sommerland", "u": "/straand-preview/en/experiences/things-to-do/#straand-sommerland", "x": "Sandy beach just below the hotel with trampolines, a big water trampoline, beach volleyball and canoe, rowing boat and pedal boat hire. The beach bar opens around high summer.", "k": "Explore Vrådal"}, {"t": "Sølvsmedtunet and Nisseloftet", "u": "/straand-preview/en/experiences/things-to-do/#solvsmedtunet", "x": "The hotel's next-door neighbour: master silversmith Astrid Søftestad makes jewellery and bunad silver. There is also a gift shop and Nisseloftet, a Christmas shop open all year.", "k": "Explore Vrådal"}, {"t": "Vrådal Golf on Fossøy", "u": "/straand-preview/en/experiences/things-to-do/#vradal-golf", "x": "Nine holes on Fossøy in Lake Nisser, just across the water from the hotel, with a driving range and golf café. Voted best golf course in Norway by Golfamore members in 2025.", "k": "Explore Vrådal"}, {"t": "Fossøy nature and culture trail", "u": "/straand-preview/en/experiences/things-to-do/#fossoy-kultursti", "x": "Easy 4 km loop across the locks and around Fossøy, with 18 information boards on archaeology, forestry, wildlife and the Småstraum lock. About an hour.", "k": "Explore Vrådal"}, {"t": "Kviteseid Old Church", "u": "/straand-preview/en/experiences/things-to-do/#kviteseid-gamle-kyrkje", "x": "Medieval stone church by Lake Kviteseidvatnet, one of the best preserved in Telemark. The ceiling has painted panels from 1714. Summer guided tours via Kviteseid bygdetun.", "k": "Explore Vrådal"}, {"t": "Vrådal Panorama", "u": "/straand-preview/en/experiences/things-to-do/#vradal-panorama", "x": "The ski resort on the mountainside above Vrådal has 18 slopes and 8 lifts. The wood-fired Panorama sauna overlooks the lake and is rented by the two-hour slot.", "k": "Explore Vrådal"}, {"t": "Venelifjell", "u": "/straand-preview/en/experiences/things-to-do/#venelifjell", "x": "Family-friendly summit hike to over 900 m with views across Lake Nisser. The path crosses boardwalks over marshland and passes a small lake. About 4 km return, 2–3 hours.", "k": "Explore Vrådal"}, {"t": "Norsk Skieventyr, Morgedal", "u": "/straand-preview/en/experiences/things-to-do/#norsk-skieventyr-morgedal", "x": "Ski and polar history museum in the cradle of skiing, telling the story of Sondre Norheim. The Olympic flame was lit in Morgedal for the 1952, 1960 and 1994 Winter Games.", "k": "Explore Vrådal"}, {"t": "Treetop walkway at Hamaren, Fyresdal", "u": "/straand-preview/en/experiences/things-to-do/#hamaren-tretoppvegen", "x": "A one-kilometre, step-free walkway rising through the treetops to a viewing ring 15 metres above ground, looking out over Lake Fyresvatn. Open all year.", "k": "Explore Vrådal"}, {"t": "Telemark Canal", "u": "/straand-preview/en/experiences/things-to-do/#telemarkskanalen", "x": "The 105 km waterway between Skien and Dalen has 18 locks. The old canal boats MS Victoria and MS Henrik Ibsen sail the full route.", "k": "Explore Vrådal"}, {"t": "Vest-Telemark Museum and Eidsborg Stave Church", "u": "/straand-preview/en/experiences/things-to-do/#vest-telemark-museum-eidsborg", "x": "The main museum at Eidsborg has exhibitions and an open-air farm, next to the 13th-century Eidsborg stave church. Several guided church tours a day in season.", "k": "Explore Vrådal"}, {"t": "Z-Museum, Treungen", "u": "/straand-preview/en/experiences/things-to-do/#z-museum", "x": "Private museum at the south end of Lake Nisser with over 50 themed exhibitions: vintage cars, telephones, hats, sewing machines, an old village shop and more. Renewed every year.", "k": "Explore Vrådal"}, {"t": "Heddal Stave Church", "u": "/straand-preview/en/experiences/things-to-do/#heddal-stavkirke", "x": "Norway's largest stave church stands by Lake Heddalsvatnet just west of Notodden. It is still in use as the parish church for Heddal.", "k": "Explore Vrådal"}, {"t": "Gaustatoppen and Gaustabanen", "u": "/straand-preview/en/experiences/things-to-do/#gaustatoppen", "x": "Telemark's highest mountain (1,883 m) looks out over much of southern Norway. Hike up from Stavsro, or take Gaustabanen, the railway inside the mountain, almost to the top.", "k": "Explore Vrådal"}, {"t": "Rjukan–Notodden World Heritage and Vemork", "u": "/straand-preview/en/experiences/things-to-do/#rjukan-notodden-unesco", "x": "A UNESCO World Heritage Site since 2015 telling the story of Norsk Hydro and Norway's industrial pioneers. The Industrial Workers Museum at Vemork also covers the heavy water sabotage.", "k": "Explore Vrådal"}, {"t": "Norway's first Bikers Welcome hotel", "u": "/straand-preview/en/experiences/motorcycling/", "x": "Telemark has some of Norway's best roads to ride: hairpins, steep climbs and routes between fjord and mountain. With HUBRiding you stay at Straand, unpack once and ride a new route every day.", "k": "Motorcycling"}, {"t": "Cars, Bikes & Coffee", "u": "/straand-preview/en/experiences/motorcycling/#mc-events", "x": "1 May: Season opening on the roof terrace with coffee, lunch and the sound of engines.", "k": "Motorcycling"}, {"t": "Riding refresher", "u": "/straand-preview/en/experiences/motorcycling/#mc-events", "x": "Second weekend in May: Rider training on Fyresdal airfield.", "k": "Motorcycling"}, {"t": "Triumph Nordic Treff", "u": "/straand-preview/en/experiences/motorcycling/#mc-events", "x": "13–15 August 2027: A weekend of riding and community, with Triumph Motorcycles Nordic.", "k": "Motorcycling"}, {"t": "Straandtreffet", "u": "/straand-preview/en/experiences/motorcycling/#mc-events", "x": "Third weekend in September: The highlight of the year for motorcyclists and the season finale in Telemark.", "k": "Motorcycling"}, {"t": "How do I book a room?", "u": "/straand-preview/en/about/faq/#booking-1", "x": "Choose your dates and number of guests in the booking bar at the top of the page to see available rooms and today's rates. You can also call reception on +47 35 06 90 00.", "k": "FAQ"}, {"t": "How much does a room cost?", "u": "/straand-preview/en/about/faq/#booking-2", "x": "The price depends on dates, room type and package. You see all rates when you choose dates in the booking.", "k": "FAQ"}, {"t": "Is breakfast included?", "u": "/straand-preview/en/about/faq/#booking-3", "x": "It is shown in the rate you choose in the booking. Breakfast can also be bought at the hotel.", "k": "FAQ"}, {"t": "How do I cancel or change my booking?", "u": "/straand-preview/en/about/faq/#booking-4", "x": "Bookings made directly with us can be changed or cancelled until 2 pm the day before arrival. For some events, such as Christmas and New Year, the deadline is two weeks. A no-show is charged for the first night.", "k": "FAQ"}, {"t": "When do I pay?", "u": "/straand-preview/en/about/faq/#booking-5", "x": "On arrival. At check-in we take an authorisation on your card, so the amount is reserved until check-out. If you pay cash, we need a card as a guarantee.", "k": "FAQ"}, {"t": "Which payment methods do you accept?", "u": "/straand-preview/en/about/faq/#booking-6", "x": "Visa, Mastercard, Eurocard, Diners, JCB, BankAxept and Vipps. The hotel does not exchange currency, and cash withdrawals are not possible.", "k": "FAQ"}, {"t": "Can I pay by invoice?", "u": "/straand-preview/en/about/faq/#booking-7", "x": "Invoicing must be agreed before the stay, requires a credit check and applies to stays over NOK 5,000. We do not invoice private individuals.", "k": "FAQ"}, {"t": "Do you sell gift cards?", "u": "/straand-preview/en/about/faq/#booking-8", "x": "Yes. Gift cards can be used for an overnight stay with breakfast, dinner in the restaurant, an aperitif with storytelling, the Straand burger and pizza, and cabin or apartment stays.", "k": "FAQ"}, {"t": "Can I stay if I am under 18?", "u": "/straand-preview/en/about/faq/#booking-9", "x": "No, nobody under 18 can book or stay alone. Guests under 18 must be accompanied by an adult who is responsible during the stay.", "k": "FAQ"}, {"t": "When are check-in and check-out?", "u": "/straand-preview/en/about/faq/#ankomst-1", "x": "Check-in from 3 pm, from 4 pm in June–September. Check-out before 11 am.", "k": "FAQ"}, {"t": "Can I check in early?", "u": "/straand-preview/en/about/faq/#ankomst-2", "x": "If your room is ready, you check in straight away. Otherwise you can use all the facilities, such as the pool and restaurant, until it is.", "k": "FAQ"}, {"t": "Can I check out late?", "u": "/straand-preview/en/about/faq/#ankomst-3", "x": "Yes, if we have capacity. Arrange it at reception the evening before at the latest. It costs NOK 100 per room per extra hour.", "k": "FAQ"}, {"t": "Is reception open 24 hours?", "u": "/straand-preview/en/about/faq/#ankomst-4", "x": "Yes, reception is open around the clock on +47 35 06 90 00.", "k": "FAQ"}, {"t": "Is there parking, and what does it cost?", "u": "/straand-preview/en/about/faq/#ankomst-5", "x": "Parking is free. The hotel's outdoor car park has approx. 100 spaces for cars and motorcycles, right next to the hotel.", "k": "FAQ"}, {"t": "Can I charge my electric car?", "u": "/straand-preview/en/about/faq/#ankomst-6", "x": "Yes. There are EV chargers at the hotel, both for hotel guests and Charge365 chargers paid in the app.", "k": "FAQ"}, {"t": "What room types do you have?", "u": "/straand-preview/en/about/faq/#rom-1", "x": "Historic rooms, standard doubles, family rooms, demi-suites, accessible rooms and singles: 125 rooms in total.", "k": "FAQ"}, {"t": "What is in the rooms?", "u": "/straand-preview/en/about/faq/#rom-2", "x": "All rooms have TV and wifi, and a bathroom with shower or bath, toilet and hairdryer. The demi-suites also have a coffee machine and a balcony.", "k": "FAQ"}, {"t": "Do you have wheelchair-accessible rooms?", "u": "/straand-preview/en/about/faq/#rom-3", "x": "We have two rooms with wide doors, a large bathroom and room for a wheelchair, and some family rooms can also be used. If you need a shower chair or raised toilet seat, let us know in good time.", "k": "FAQ"}, {"t": "Do you have allergy-friendly rooms?", "u": "/straand-preview/en/about/faq/#rom-4", "x": "Yes, the hotel has allergy rooms. Let us know when you book.", "k": "FAQ"}, {"t": "Can I bring my dog or other pets?", "u": "/straand-preview/en/about/faq/#rom-5", "x": "Yes, but tell us in advance, as only some rooms allow pets. The fee is NOK 300 per room per stay. Pets are not allowed in the shared areas, and you get your own entrance. Service and guide dogs are exempt.", "k": "FAQ"}, {"t": "Is the hotel non-smoking?", "u": "/straand-preview/en/about/faq/#rom-6", "x": "Straand is a non-smoking hotel. Smoking in the room is charged NOK 1,500, but there are outdoor areas where smoking is allowed.", "k": "FAQ"}, {"t": "Do you have cabins or apartments?", "u": "/straand-preview/en/about/faq/#rom-7", "x": "Yes, through Vrådal Booking we rent out cabins and holiday apartments in Vrådal for self-catering stays.", "k": "FAQ"}, {"t": "When are breakfast, lunch and dinner served?", "u": "/straand-preview/en/about/faq/#mat-1", "x": "Breakfast from 8 am. Lunch 12–6 pm in the piano bar or on the terrace. Dinner has seatings between 7 and 9 pm, so tell us your preferred time.", "k": "FAQ"}, {"t": "Can I eat at the hotel without staying?", "u": "/straand-preview/en/about/faq/#mat-2", "x": "Yes, everyone is welcome. Call +47 35 06 90 00 to book a table.", "k": "FAQ"}, {"t": "Do you cater for allergies and gluten-free diets?", "u": "/straand-preview/en/about/faq/#mat-3", "x": "Yes. Several dishes can be served with gluten-free bread. Tell us about allergies when you book a table or on arrival.", "k": "FAQ"}, {"t": "Do you serve afternoon tea?", "u": "/straand-preview/en/about/faq/#mat-4", "x": "Yes, 12–5 pm in our historic lounges.", "k": "FAQ"}, {"t": "When are the bar and terrace open?", "u": "/straand-preview/en/about/faq/#mat-5", "x": "Fram Bar opens at noon, with the bar menu until 9 pm. The terrace opens at noon with food until 6 pm, weather permitting.", "k": "FAQ"}, {"t": "When is the beach bar open?", "u": "/straand-preview/en/about/faq/#mat-6", "x": "The beach bar on Lake Nisser is open approx. 23 June–20 August.", "k": "FAQ"}, {"t": "What is \"the taste of Telemark\"?", "u": "/straand-preview/en/about/faq/#mat-7", "x": "It is the kitchen's idea: local, seasonal produce from around us, such as game, berries and mushrooms in autumn.", "k": "FAQ"}, {"t": "Is there a pool and sauna?", "u": "/straand-preview/en/about/faq/#fasiliteter-1", "x": "Yes. The hotel has a heated indoor pool, open 7 am–7 pm. The saunas are open 7–9 am and 4–7 pm.", "k": "FAQ"}, {"t": "Can day visitors use the pool?", "u": "/straand-preview/en/about/faq/#fasiliteter-2", "x": "Yes, both day visitors and hotel guests can use the pool, the playground and the beach.", "k": "FAQ"}, {"t": "Is there free wifi?", "u": "/straand-preview/en/about/faq/#fasiliteter-3", "x": "Yes, free wifi throughout the hotel.", "k": "FAQ"}, {"t": "Do you have a gym?", "u": "/straand-preview/en/about/faq/#fasiliteter-4", "x": "Yes, the hotel has a fitness room.", "k": "FAQ"}, {"t": "Is Straand good for families?", "u": "/straand-preview/en/about/faq/#familie-1", "x": "Yes. We have family rooms, a playroom with Nintendo Wii and board games, and in summer a beach, trampolines and water activities at Straand Sommerland.", "k": "FAQ"}, {"t": "What can children do when it rains?", "u": "/straand-preview/en/about/faq/#familie-2", "x": "Swim in the indoor pool, play in the playroom or borrow toy boxes and board games.", "k": "FAQ"}, {"t": "What is Straand Sommerland?", "u": "/straand-preview/en/about/faq/#familie-3", "x": "Our own beach club on Lake Nisser, with a sandy beach, swimming, SUP, kayaks, canoes, pedal boats, trampolines, beach volleyball and kubb, and a beach bar with simple summer food.", "k": "FAQ"}, {"t": "What is MS Fram?", "u": "/straand-preview/en/about/faq/#aktiviteter-1", "x": "The hotel's vintage boat from 1909. It sails on Lake Nisser and Vråvatn through the Småstraum and Storstraum locks, from mid-May to early October.", "k": "FAQ"}, {"t": "Can we eat on board MS Fram?", "u": "/straand-preview/en/about/faq/#aktiviteter-2", "x": "Coffee, drinks and snacks are served on board. Fresh baguettes or tapas platters can be pre-ordered.", "k": "FAQ"}, {"t": "Can I hire a canoe, kayak or bike?", "u": "/straand-preview/en/about/faq/#aktiviteter-3", "x": "Yes. Canoes, kayaks, bikes and e-bikes are hired at reception or at the Straand Sommerland bar. Life jackets are required by law, and you can hire one for NOK 50.", "k": "FAQ"}, {"t": "Can I play golf nearby?", "u": "/straand-preview/en/about/faq/#aktiviteter-4", "x": "Yes, on the 9-hole course on Fossøy, an island in Lake Nisser close to the hotel. The hotel rents out golf carts (the renter must be over 18).", "k": "FAQ"}, {"t": "Where can we go hiking?", "u": "/straand-preview/en/about/faq/#aktiviteter-5", "x": "Vrådal has marked routes for families and experienced hikers. Venelifjellet (905 m) has panoramic views, and Gaustatoppen makes a great day trip.", "k": "FAQ"}, {"t": "Are you motorcycle friendly?", "u": "/straand-preview/en/about/faq/#aktiviteter-6", "x": "Yes, Straand was Norway's first Bikers Welcome hotel and created HUBRiding: 15 routes with guaranteed bends, free parking, vehicle washing and gear drying.", "k": "FAQ"}, {"t": "What is there to do in Vrådal in winter?", "u": "/straand-preview/en/about/faq/#aktiviteter-7", "x": "Ski slopes, forest ski trails, fireside evenings, the pool and sauna, and play for the children.", "k": "FAQ"}, {"t": "Can we hold a meeting or conference with you?", "u": "/straand-preview/en/about/faq/#arrangementer-1", "x": "Yes. The Vrådal Hall is about 660 m² and seats 400 in one room. It can be divided, and there are several smaller rooms and breakout rooms.", "k": "FAQ"}, {"t": "What equipment do the meeting rooms have?", "u": "/straand-preview/en/about/faq/#arrangementer-2", "x": "All meeting rooms have a PA system, screen and flip chart, and the breakout rooms have a screen and flip chart. Wifi throughout, and a 4.5-metre drive-in door straight into the hall.", "k": "FAQ"}, {"t": "Can you arrange team building and activities?", "u": "/straand-preview/en/about/faq/#arrangementer-3", "x": "Yes, for example guided mountain hikes, canoe trips, trail biking, climbing, snowshoe and ski trips, ski instruction and team-building competitions.", "k": "FAQ"}, {"t": "Can we have our wedding at Straand?", "u": "/straand-preview/en/about/faq/#arrangementer-4", "x": "Yes. A ceremony in the apple orchard, a party in historic rooms, a vintage car to the church and MS Fram for up to 90 guests.", "k": "FAQ"}, {"t": "Do you host Christmas parties?", "u": "/straand-preview/en/about/faq/#arrangementer-5", "x": "Yes, on six weekends before Christmas, with home-made Christmas food in the historic lounges and a show. Rooms are booked separately from shows and events.", "k": "FAQ"}, {"t": "What is the Straand Festival?", "u": "/straand-preview/en/about/faq/#arrangementer-6", "x": "The annual music and dance festival with Norwegian dance music on several stages, on the weekend of 30 October–1 November.", "k": "FAQ"}, {"t": "Where is the hotel?", "u": "/straand-preview/en/about/faq/#beliggenhet-1", "x": "Kviteseidvegen 1698, 3853 Vrådal, at the northern end of Lake Nisser in West Telemark.", "k": "FAQ"}, {"t": "How far is it from Oslo?", "u": "/straand-preview/en/about/faq/#beliggenhet-2", "x": "Vrådal is in West Telemark, a natural stop between Oslo and Bergen. Kristiansand and Larvik are 2–3 hours away by car, Stavanger and Bergen 5–6 hours. Getting here has directions from Oslo.", "k": "FAQ"}, {"t": "Can I get to the hotel by bus?", "u": "/straand-preview/en/about/faq/#beliggenhet-3", "x": "Yes, the bus stop \"Straand\" is right next to the hotel. Check routes and times with Entur (entur.no).", "k": "FAQ"}, {"t": "How do I contact you?", "u": "/straand-preview/en/about/faq/#beliggenhet-4", "x": "Call +47 35 06 90 00 (reception is open 24 hours) or email straand@straand.no.", "k": "FAQ"}, {"t": "How old is Straand Hotel?", "u": "/straand-preview/en/about/faq/#historie-1", "x": "Straand became a coaching inn in 1864 and has been run by the same family for five generations. Today Katrine and Lars Arne Straand are the hosts.", "k": "FAQ"}, {"t": "What is De Historiske?", "u": "/straand-preview/en/about/faq/#historie-2", "x": "An association of historic hotels and restaurants in Norway. Straand Hotel is a member.", "k": "FAQ"}, {"t": "What does the hotel do for the environment?", "u": "/straand-preview/en/about/faq/#historie-3", "x": "Straand is Eco-Lighthouse certified, uses local produce, reduces food waste by serving plated meals most of the year, and takes part in making the region a sustainable destination.", "k": "FAQ"}, {"t": "Motorists’ paradise: Why Telemark, Vrådal and Straand Hotel offer Norway’s coolest driving experiences", "u": "/straand-preview/en/blog/driving-holiday-in-telemark/", "x": "Here you can use the hotel as a base, leave your luggage in your room and spend your days exploring Telemark’s many winding…", "k": "Blog"}, {"t": "Autumn in Vrådal: 10 fantastic things you can do on your autumn holiday with Straand Hotel as a base", "u": "/straand-preview/en/blog/autumn-in-vradal-10-things/", "x": "When the heat of summer lets go in Telemark, Vrådal transforms into a living painting in fiery red, golden and deep orange colours. Autumn is one of the most beautiful and peaceful times to visit the Norwegian mountains. The…", "k": "Blog"}, {"t": "The 5 most beautiful sights in and around Vrådal", "u": "/straand-preview/en/blog/the-5-most-beautiful-sights/", "x": "Vrådal is a place where nature is allowed to be the main attraction. Here you will find beautiful lakes, mountains, forests and viewpoints that make it easy to stop and just enjoy the surroundings. Whetheryou visit Vrådal in the…", "k": "Blog"}, {"t": "What can you do in Vrådal with children? A guide to family holidays in Telemark.", "u": "/straand-preview/en/blog/vradal-with-children/", "x": "Vrådal is a fantastic starting point for a family holiday in Telemark. Here you will find mountains, forests and lakes, combined with activities for both young and old children. But what can you really do in Vrådal with children?…", "k": "Blog"}, {"t": "A historic hotel on Lake Nisser, Vrådal", "u": "/straand-preview/en/", "x": "For us, hospitality is more than a tradition. It is an inheritance passed down through five generations. Since 1864 we have welcomed guests to Vrådal, and we want you to feel as at home here as we do.", "k": ""}, {"t": "Christmas and New Year at Straand Hotel", "u": "/straand-preview/en/christmas-and-new-year/", "x": "We at Straand Hotel welcome you and yours to a pleasant Christmas and New Year celebration with us.", "k": "Christmas"}, {"t": "Christmas & New Year", "u": "/straand-preview/en/christmas-and-new-year/2025/", "x": "From cosy Christmas traditions to New Year celebrations with fine flavours. From candlelight and winter atmosphere to warm moments around the table. Welcome to Christmas and New Year with us at Straand.", "k": "Christmas &amp; New Year in Vrådal"}, {"t": "(H)julebord – Christmas party for motor enthusiasts", "u": "/straand-preview/en/christmas-parties/motor-christmas-party/", "x": "Saturday 21 November – A new meeting place. A new tradition. The same passion.", "k": "Christmas"}, {"t": "Straand & Wallmanns", "u": "/straand-preview/en/christmas-parties/wallmans-on-tour/", "x": "Straand Hotel invites you to an evening with Wallmans On Tour. Look forward to a formidable dinner, a spectacular show, and a party atmosphere you won’t soon forget!", "k": "Christmas"}, {"t": "Business to business", "u": "/straand-preview/en/meetings-and-conferences/groups-and-tour-operators/", "x": "Welcome to beautiful Vrådal! – We work with tour operators from all over the world, and now we look forward to showing you around beautiful Vrådal in Telemark!", "k": "Business &amp; conferences"}, {"t": "Band trips", "u": "/straand-preview/en/meetings-and-conferences/groups-and-tour-operators/band-trips/", "x": "Time to plan new band experiences", "k": "Groups and tour operators (B2B)"}, {"t": "Seniors", "u": "/straand-preview/en/meetings-and-conferences/groups-and-tour-operators/seniors/", "x": "Let the beautiful mountain village of Vrådal charm you! As a senior you can enjoy beautiful nature and good food, and choose from a wide range of activities.", "k": "Groups and tour operators (B2B)"}, {"t": "Route suggestions", "u": "/straand-preview/en/meetings-and-conferences/groups-and-tour-operators/tour-ideas/", "x": "Our selected day trips and recommended arrival and departure routes", "k": "Groups and tour operators (B2B)"}, {"t": "Company Christmas parties", "u": "/straand-preview/en/meetings-and-conferences/company-christmas-parties/", "x": "Company Christmas parties with a show and overnight stay in Vrådal. Six weekends from 13 November to 20 December 2026, with options for large groups.", "k": "Business &amp; conferences"}, {"t": "Company kick-off at Straand Hotel in Vrådal", "u": "/straand-preview/en/meetings-and-conferences/kick-off/", "x": "Bring the whole company together: a conference in the Vrådal Hall, dinner and a party in the evening, outdoor activities and rooms under one roof.", "k": "Business &amp; conferences"}, {"t": "Leadership retreats and board meetings in Vrådal", "u": "/straand-preview/en/meetings-and-conferences/leadership-retreats/", "x": "We have unique and intimate meeting places for your board meeting or leadership retreat!", "k": "Business &amp; conferences"}, {"t": "Meeting rooms, conference hall and technical equipment", "u": "/straand-preview/en/meetings-and-conferences/meeting-rooms-and-equipment/", "x": "The 660 m² Vrådal Hall, breakout rooms, stage, lighting and sound, break areas and easy access with a drive-in door straight into the hall.", "k": "Business &amp; conferences"}, {"t": "Summer parties by Lake Nisser", "u": "/straand-preview/en/meetings-and-conferences/summer-parties/", "x": "We invite you to a party both outside and inside our holiday paradise. Vrådal is a unique destination that offers a multitude of opportunities!", "k": "Business &amp; conferences"}, {"t": "Straand Akademia", "u": "/straand-preview/en/meetings-and-conferences/straand-akademia/", "x": "We contribute to the success of the businesses of the future.", "k": "Business &amp; conferences"}, {"t": "Team building in Telemark", "u": "/straand-preview/en/meetings-and-conferences/team-building/", "x": "Build the good team spirit in adventurous surroundings at Straand Hotel.", "k": "Business &amp; conferences"}, {"t": "Veteran boat, car and own bus", "u": "/straand-preview/en/meetings-and-conferences/transport-and-vintage-vehicles/", "x": "Feel free to rent our beautiful veteran ship M/S Fram for a fantastic trip on Nisser. We also have our own vintage car and bus that are at your disposal if desired. Get in touch and we will put together the perfect packa", "k": "Business &amp; conferences"}, {"t": "Straand photo gallery", "u": "/straand-preview/en/about/photo-gallery/", "x": "Straand photo gallery", "k": "About"}, {"t": "On the way: From Kristiansand", "u": "/straand-preview/en/about/getting-here/from-kristiansand/", "x": "From Kristiansand the journey takes you up to Straand Hotel through beautiful scenery of forests, lakes and mountains", "k": "Getting here &amp; parking"}, {"t": "On the way: From Oslo – alternative route", "u": "/straand-preview/en/about/getting-here/from-oslo-alternative-route/", "x": "An alternative route from Oslo where you can visit cultural-historical sights and local producers", "k": "Getting here &amp; parking"}, {"t": "On the way: From Oslo", "u": "/straand-preview/en/about/getting-here/from-oslo/", "x": "From urban Oslo, via the historic Telemark Canal with its impressive locks, to the historic Straand Hotel in magnificent scenery – the journey becomes an experience in itself", "k": "Getting here &amp; parking"}, {"t": "On the way: From Sandefjord/Larvik", "u": "/straand-preview/en/about/getting-here/from-sandefjord-larvik/", "x": "From Sandefjord/Larvik to Straand Hotel it is a 2 hour 30 minute drive through varied landscapes, from towns to farmland and small villages.", "k": "Getting here &amp; parking"}, {"t": "On the way in: Slow travel from Eastern Norway", "u": "/straand-preview/en/about/getting-here/public-transport/", "x": "A cultural-historical slow journey in fantastic Telemark with experiences along the entire route. You travel by train, the Telemark Canal and bus into the heart of Telemark. Ibsen’s birthplace Skien, Norway’s most beauti", "k": "Getting here &amp; parking"}, {"t": "Onward: Towards Bergen", "u": "/straand-preview/en/about/getting-here/onward-to-bergen/", "x": "Heading on towards Bergen you drive through magnificent scenery over high mountains and through western fjords", "k": "Getting here &amp; parking"}, {"t": "Onward: Towards Sørlandet", "u": "/straand-preview/en/about/getting-here/onward-to-the-south-coast/", "x": "Visit idyllic south-coast gems and experience Norwegian cultural history on your way south", "k": "Getting here &amp; parking"}, {"t": "Onward: Towards Stavanger", "u": "/straand-preview/en/about/getting-here/onward-to-stavanger/", "x": "Taking local roads on towards Stavanger, you can experience magnificent and varied scenery", "k": "Getting here &amp; parking"}, {"t": "Map", "u": "/straand-preview/en/about/map/", "x": "With our online map you can easily plan your experience – from historic monuments and exciting activities to museums and shops offering local treasures.", "k": "About"}, {"t": "Want to work with us?", "u": "/straand-preview/en/about/jobs/", "x": "We are always looking for talented people", "k": "About"}, {"t": "Join the team", "u": "/straand-preview/en/about/jobs/summer-season-hotel-staff/", "x": "Committed hotel staff for the summer season", "k": "Vacancies"}, {"t": "Receptionist wanted for the historic Straand Hotel in beautiful Vrådal, Telemark", "u": "/straand-preview/en/about/jobs/night-receptionist/", "x": "Straand Hotel is growing and is looking for positive, reliable, structured, flexible and responsible people for our reception.", "k": "Vacancies"}, {"t": "We are looking for a reception manager for the historic Straand Hotel", "u": "/straand-preview/en/about/jobs/reception-manager/", "x": "We are looking for a reception manager for the historic Straand Hotel", "k": "Vacancies"}, {"t": "Caretaker wanted", "u": "/straand-preview/en/about/jobs/caretaker/", "x": "Are you our new caretaker?", "k": "Vacancies"}, {"t": "Environment and sustainability", "u": "/straand-preview/en/about/sustainability/", "x": "With a heart for Vrådal", "k": "About"}, {"t": "Cars, Bikes & Coffee", "u": "/straand-preview/en/experiences/events/cars-bikes-coffee/", "x": "On May 1st every year, we invite you to a driveout and lunch at the historic Straand Hotel.", "k": "Events"}, {"t": "Dyrsku’n - 8 to 10 September 2023", "u": "/straand-preview/en/experiences/events/dyrsku-2023/", "x": "More information to come", "k": "Events"}, {"t": "Hotel rooms Thursday - Sunday", "u": "/straand-preview/en/experiences/events/ifmr-registration/", "x": "[gravityform id=\"6\"]", "k": "Events"}, {"t": "Cultural-historical beer festival – 20–22 October", "u": "/straand-preview/en/experiences/events/cultural-history-beer-festival/", "x": "Cultural-historical beer festival – 20–22 October", "k": "Events"}, {"t": "Narvesen Tour", "u": "/straand-preview/en/experiences/events/narvesen-tour/", "x": "Narvesen Tour", "k": "Events"}, {"t": "Felicity Sax live – music, atmosphere and a party on Friday 17 October", "u": "/straand-preview/en/experiences/events/sax-party-night/", "x": "Felicity Sax live – music, atmosphere and a party on Friday 17 October", "k": "Events"}, {"t": "Summer Scramble at Straand, 5 September", "u": "/straand-preview/en/experiences/events/summer-scramble/", "x": "Golf in beautiful scenery with great experiences", "k": "Events"}, {"t": "Catering trade fair, 6 March 2024", "u": "/straand-preview/en/experiences/events/catering-trade-fair-suppliers/", "x": "Catering trade fair, 6 March 2024", "k": "Events"}, {"t": "Catering trade fair, 6 March 2024", "u": "/straand-preview/en/experiences/events/catering-trade-fair/", "x": "Catering trade fair, 6 March 2024", "k": "Events"}, {"t": "Straand Bilfinale", "u": "/straand-preview/en/experiences/events/straand-car-finale/", "x": "End of season for the car people — all brands, all clubs, all enthusiasts welcome to this year’s happening in Vrådal.", "k": "Events"}, {"t": "Straand Car Weekend", "u": "/straand-preview/en/experiences/events/straand-car-weekend/", "x": "Straand Hotel, which is a hotel affiliated with the Historic Hotels and Eateries in Norway, aims to become Norway’s best hotel for motorcycle and car tourists, regardless of the age and size of the vehicle.", "k": "Events"}, {"t": "Straand on ICE 2024 - 23 to 25 February 2024", "u": "/straand-preview/en/experiences/events/straand-on-ice/", "x": "YOU CAN DRIVE WITH", "k": "Events"}, {"t": "Straand Sykkel Treff (Watt-treffet) - 31 May to 2 June 2024", "u": "/straand-preview/en/experiences/events/straand-watt-meet/", "x": "Do you want to join in cycling and maybe you intend to buy an electric bike?", "k": "Events"}, {"t": "Straand Treffet 2026 - 18 to 20 September", "u": "/straand-preview/en/experiences/events/straand-meet/", "x": "Welcome to Straand-Treffet 2026, a worthy end to the motorcycle season. Here you can test ride many motorcycles from various dealers and importers, take part in a guided tour on beautiful motorcycle roads and meet others", "k": "Events"}, {"t": "Triumph Nordic Treff 2027 – 13 to 15 August", "u": "/straand-preview/en/experiences/events/triumph-nordic-meet/", "x": "Welcome to a friendly motorcycle weekend – at Norway's renowned motorcycle hotel, with great riding on the Hubriding.no routes around Straand Hotel, Vrådal in Telemark, Kviteseidvegen 1698, 3853 Vrådal.", "k": "Events"}, {"t": "Valentine's dinner", "u": "/straand-preview/en/experiences/events/valentines-dinner/", "x": "Valentine's dinner", "k": "Events"}, {"t": "3 Verdiløse play Jokke & Valentinerne", "u": "/straand-preview/en/experiences/events/3-verdilose-concert/", "x": "3 Verdiløse play Jokke & Valentinerne", "k": "Events"}, {"t": "Game night at Straand Hotel, 11 October", "u": "/straand-preview/en/experiences/events/wild-game-night/", "x": "Game night at Straand Hotel, 11 October", "k": "Events"}, {"t": "Classic Cars", "u": "/straand-preview/en/experiences/cars/", "x": "Straand Hotel aims to become Norway’s best hotel for motorcycle and car tourists.", "k": "Experiences"}, {"t": "Family holidays at Straand Hotel", "u": "/straand-preview/en/experiences/family-holiday/", "x": "A heated indoor pool, playroom, family rooms and activities all year, by Lake Nisser in Vrådal.", "k": "Experiences"}, {"t": "Golf in Vrådal", "u": "/straand-preview/en/experiences/golf/", "x": "Play Norway's best golf course – surrounded by Lake Nisser, mountains and forest. Stay at Straand Hotel and enjoy golf in Telemark.", "k": "Experiences"}, {"t": "HUBRiding", "u": "/straand-preview/en/experiences/motorcycling/hubriding/", "x": "Straand Hotel aims to become Norway’s best hotel for motorcycle and car tourists.", "k": "Motorcycling"}, {"t": "Riding refresher for all everyday motorcyclists", "u": "/straand-preview/en/experiences/motorcycling/rider-training/", "x": "Welcome to rider development with training-ground exercises on asphalt and gravel (for those who wish) on Saturday 9 May 2026 at Fyresdal airfield. There will be professional content and socialising at Straand Hotel thro", "k": "Motorcycling"}, {"t": "Taste of Fjell-Telemark Week", "u": "/straand-preview/en/experiences/taste-of-fjell-telemark-survey/", "x": "Taste of Fjell-Telemark Week", "k": "Experiences"}, {"t": "By the water’s edge, just below the hotel, you will find Straand Sommerland.", "u": "/straand-preview/en/experiences/straand-summerland/", "x": "By the water’s edge, just below the hotel, you will find Straand Sommerland.", "k": "Experiences"}, {"t": "An adventure on two wheels", "u": "/straand-preview/en/experiences/cycling/", "x": "Hubriding Cycling offers accessible trails, exciting country roads and cycling routes close to most cities and towns. Panoramic views and beautiful scenery can be found around every turn – a cycling holiday you’re sure t", "k": "Experiences"}, {"t": "Day trip ideas", "u": "/straand-preview/en/experiences/tour-suggestions/", "x": "Day trip ideas", "k": "Experiences"}, {"t": "Tour suggestion: Fruit safari in Telemark", "u": "/straand-preview/en/experiences/tour-suggestions/fruit-safari-in-telemark/", "x": "Telemark is known for its lush climate, perfect for growing fruit and berries. Join a tasty fruit safari in Mid-Telemark, starting and finishing at Straand Hotel!", "k": "Day trip ideas"}, {"t": "Route suggestion: Gaustatoppen and Gaustabanen", "u": "/straand-preview/en/experiences/tour-suggestions/gaustatoppen-and-gaustabanen/", "x": "Experience Telemark’s highest mountain peak and Norway’s best view", "k": "Day trip ideas"}, {"t": "Four full days for everyone", "u": "/straand-preview/en/experiences/tour-suggestions/hubriding-telemark-bucket-list/", "x": "In Telemark you have a lot to choose from…", "k": "Day trip ideas"}, {"t": "MC & CAR: EXPLORE THE BEST OF NORWAY", "u": "/straand-preview/en/experiences/tour-suggestions/motorcycle-and-car-explore-the-best-of-norway/", "x": "TELEMARK IS A WELL-KEPT SECRET FOR MOTORCYCLISTS AND CAR ENTHUSIASTS You and your friends don’t have to travel to southern Europe to find the best driving terrain and the greatest experiences on two and four wheels. Norw", "k": "Day trip ideas"}, {"t": "Route suggestion: MS Fram and Sølvsmedtunet", "u": "/straand-preview/en/experiences/tour-suggestions/ms-fram-and-solvsmedtunet/", "x": "Enjoy a relaxing day on a lock cruise with MS Fram and a visit to our neighbor at Sølvsmedtunet", "k": "Day trip ideas"}, {"t": "Day trip to Rjukan", "u": "/straand-preview/en/experiences/tour-suggestions/rjukan-and-vemork/", "x": "Experience the Norwegian Industrial Workers Museum and the story of the heavy water sabotage", "k": "Day trip ideas"}, {"t": "Tour suggestion: The taste of Fjell-Telemark", "u": "/straand-preview/en/experiences/tour-suggestions/taste-of-fjell-telemark/", "x": "There are plenty of mountains in Telemark. On this round trip you can taste mountain-farm food, local cheeses and baked goods, all in beautiful scenery!", "k": "Day trip ideas"}, {"t": "Discovery trip to Fyresdal", "u": "/straand-preview/en/experiences/tour-suggestions/tretoppvegen-and-z-museum/", "x": "Enjoy a great drive in magnificent nature to Fyresdal and Treungen and feel free to stop by Z-museum on the way", "k": "Day trip ideas"}, {"t": "West Telemark", "u": "/straand-preview/en/experiences/tour-suggestions/vest-telemark-round-trip-culture-route/", "x": "A great round trip in West Telemark with stops at great viewpoints and exciting museums.", "k": "Day trip ideas"}, {"t": "Route suggestion: Around Vest-Telemark (Telemark history)", "u": "/straand-preview/en/experiences/tour-suggestions/around-vest-telemark-history/", "x": "Experience the rich and varied history of Vest-Telemark on a round trip through beautiful, varied scenery", "k": "Day trip ideas"}, {"t": "Discover Vrådal - Things To Do", "u": "/straand-preview/en/experiences/things-to-do/discover-vradal/", "x": "Your guide to things to do, events, food, activities and experiences in Vrådal.", "k": "Explore Vrådal"}, {"t": "Rental products from Straand Hotel", "u": "/straand-preview/en/experiences/rentals/", "x": "Here you can find suggestions for varied activities around and from historic Straand Hotel in beautiful Vrådal, by water and on land.", "k": "Experiences"}, {"t": "Snowmobile hire – speed, freedom and mountains at their best", "u": "/straand-preview/en/experiences/rentals/snowmobile-hire/", "x": "Experience Telemark’s winter landscape on two tracks!", "k": "Rentals"}, {"t": "Hiking in Vrådal", "u": "/straand-preview/en/experiences/hiking/", "x": "Vrådal has a great terrain for hiking. Here you will find marked routes for both families with children and more experienced hikers.", "k": "Experiences"}, {"t": "Winter holiday in Vrådal", "u": "/straand-preview/en/experiences/winter-holiday/", "x": "Throughout the winter holiday week, we have curated unique experiences – from quiet mornings in nature to lively evenings with good food and company.", "k": "Experiences"}, {"t": "Enjoy Easter in the ♥ of Telemark", "u": "/straand-preview/en/experiences/winter-holiday/easter-in-vradal/", "x": "Embrace the fun and spend your Easter holiday in beautiful Vrådal in West Telemark! Here you can ski the slopes, whizz down the hill on a toboggan, go snowshoeing, and enjoy a sauna and an ice bath under the starry sky. ", "k": "Winter holiday in Vrådal"}, {"t": "Packages and offers", "u": "/straand-preview/en/packages/", "x": "Packages and offers", "k": "Home"}, {"t": "Ski package", "u": "/straand-preview/en/packages/ski-package/", "x": "Ski packages with accommodation and breakfast from NOK 1,250 per person", "k": "Packages &amp; offers"}, {"t": "Family summer in Vrådal", "u": "/straand-preview/en/packages/family-summer/", "x": "Experience fjord, mountains and holiday fun at Straand Hotel!", "k": "Packages &amp; offers"}, {"t": "Gift cards for Christmas", "u": "/straand-preview/en/packages/gift-cards/", "x": "Looking for a Christmas present for the person who has everything? Give an experience.", "k": "Packages &amp; offers"}, {"t": "Motorcycle Packages", "u": "/straand-preview/en/packages/motorcycle-packages/", "x": "Experience Southern Norway's most beautiful motorcycle roads. Welcome to a motorcycle trip to Straand Hotel in Vrådal, Telemark.", "k": "Packages &amp; offers"}, {"t": "MS Fram package with accommodation and breakfast", "u": "/straand-preview/en/packages/ms-fram-package/", "x": "Sail through beautiful islands and Northern Europe’s highest-lying locks.", "k": "Packages &amp; offers"}, {"t": "Romantic stay", "u": "/straand-preview/en/packages/romantic-stay/", "x": "Time for each other. Take a complete break from everything else and enjoy life together!", "k": "Packages &amp; offers"}, {"t": "Cycling package with accommodation and breakfast", "u": "/straand-preview/en/packages/cycling-package/", "x": "Perfect if you want to get out into nature without thinking about logistics – the bike is ready when you arrive.", "k": "Packages &amp; offers"}, {"t": "Cycling packages", "u": "/straand-preview/en/packages/cycling-packages/", "x": "Hubriding Cycling offers accessible trails, exciting country roads and cycle routes close to most towns and villages.", "k": "Packages &amp; offers"}, {"t": "Experience real winter magic with Telemark Husky Tour", "u": "/straand-preview/en/packages/telemark-husky-tour/", "x": "After a good breakfast with us at Straand, wrap up in warm clothes and head for Rauland (about an hour away). Adventure awaits – and after the trip you can enjoy hot cocoa, visit local cafés or combine the experience wit", "k": "Packages &amp; offers"}, {"t": "Treetop experience with accommodation and packed lunch", "u": "/straand-preview/en/packages/treetop-experience/", "x": "Experience Telemark from the treetops with a trip to the airy Tretoppvegen treetop walk in Fyresdal.", "k": "Packages &amp; offers"}, {"t": "Hiking package", "u": "/straand-preview/en/packages/hiking-package/", "x": "There are many hiking opportunities in Vrådal, with excellent terrain for walks of varying difficulty.", "k": "Packages &amp; offers"}, {"t": "Spring’s taste of joy", "u": "/straand-preview/en/packages/springs-taste-of-joy/", "x": "On 29 April, the Friends of Bache-Gabrielsen invite you to a flavourful event at the historic Straand Hotel", "k": "Packages &amp; offers"}, {"t": "Friends’ getaway", "u": "/straand-preview/en/packages/friends-getaway/", "x": "We want to make your visit to us special. A trip to Straand Hotel should be a memory for life.", "k": "Packages &amp; offers"}, {"t": "Winter experience: Fondue", "u": "/straand-preview/en/packages/winter-fondue/", "x": "Gather family and friends for a warm dining experience in the middle of winter!", "k": "Packages &amp; offers"}, {"t": "Winter experience: Forest Barista", "u": "/straand-preview/en/packages/winter-forest-barista/", "x": "Get the barista feeling in the heart of nature!", "k": "Packages &amp; offers"}, {"t": "Winter experience: Stargazing", "u": "/straand-preview/en/packages/winter-stargazing/", "x": "Join us for a magical evening walk under the starry sky!", "k": "Packages &amp; offers"}, {"t": "Winter experience: Trapper’s Cabin", "u": "/straand-preview/en/packages/winter-trappers-cabin/", "x": "Enjoy an intimate and unique dining experience in Norway’s smallest tavern!", "k": "Packages &amp; offers"}, {"t": "Weekend stay", "u": "/straand-preview/en/packages/weekend-stay/", "x": "We want to make your visit to us special. A trip to Straand Hotel will be a memory for life.", "k": "Packages &amp; offers"}, {"t": "Weddings at Straand Hotel", "u": "/straand-preview/en/celebrations/weddings/", "x": "Celebrate your wedding in romantic surroundings at Straand Hotel!", "k": "Weddings &amp; celebrations"}, {"t": "Confirmations, christenings and naming parties", "u": "/straand-preview/en/celebrations/confirmations-and-christenings/", "x": "We take care of the food and the arrangements so you can enjoy the day. Guests from afar get good room rates with breakfast.", "k": "Weddings &amp; celebrations"}, {"t": "Rent an atmospheric venue", "u": "/straand-preview/en/celebrations/rent-an-atmospheric-venue/", "x": "Wine cellar, stabbur, pub, dance hall, Bestemorstua and quiet rooms to work in. Rent a room of your own for a gathering, a party or work.", "k": "Weddings &amp; celebrations"}, {"t": "Venues and bar", "u": "/straand-preview/en/celebrations/venues/", "x": "Storehouse, wine cellar, fireplace lounge, Bestemorstua, restaurant, bar and pub: rooms for anything from a small, intimate party to a big celebration.", "k": "Weddings &amp; celebrations"}, {"t": "Food, programme and offers for celebrations", "u": "/straand-preview/en/celebrations/food-and-programme/", "x": "Celebration dinners, tastings, an aperitif with storytelling, band trips and Christmas parties. We plan it with you.", "k": "Weddings &amp; celebrations"}, {"t": "Afternoon tea at Straand", "u": "/straand-preview/en/eat-and-drink/afternoon-tea/", "x": "Afternoon tea in the atmospheric salons of historic Straand Hotel, served 12–5 pm.", "k": "Food &amp; drink"}, {"t": "Skjusstasjonen Pub", "u": "/straand-preview/en/eat-and-drink/fram-bar/skjusstasjonen-pub/", "x": "We have our own pub", "k": "Food &amp; drink"}, {"t": "Our menus", "u": "/straand-preview/en/eat-and-drink/menus/", "x": "Good food from local ingredients is absolutely central to us at Straand Hotel.", "k": "Food &amp; drink"}, {"t": "New! Take-away", "u": "/straand-preview/en/eat-and-drink/menus/take-away/", "x": "We make the food for you, so you have more time to spend with the people you love!", "k": "Our menus"}, {"t": "Terms & Conditions – FITs and Groups (2025/2026)", "u": "/straand-preview/en/terms-tour-operators/", "x": "Terms & Conditions – FITs and Groups (2025/2026)", "k": "Home"}, {"t": "General terms and conditions for rental products", "u": "/straand-preview/en/terms-rental-products/", "x": "Rental products means our boats, bicycles, canoes and so on", "k": "About"}, {"t": "Terms and conditions for individual guests", "u": "/straand-preview/en/terms-individual-guests/", "x": "General Terms and Conditions for Individual Travelers", "k": "About"}, {"t": "Terms and conditions for groups", "u": "/straand-preview/en/terms-groups/", "x": "General terms and conditions for groups, courses and conferences", "k": "About"}, {"t": "Terms and conditions for events", "u": "/straand-preview/en/terms-events/", "x": "General terms and conditions for events", "k": "About"}];
